/bin/bash -lc "cd /workspace && python3 - << 'PYEOF'
import openai_client as m

# Import + post-init behavior
try:
    m.OpenAIClient(api_key=\"\")
except m.OpenAIClientError as e:
    print(\"empty-key error ok:\", e)

# _extract_text for new-style payload
p1 = {\"output_text\": \"hello world\"}
print(\"new-style:\", m._extract_text(p1) == \"hello world\")

# _extract_text for legacy output[] style
p2 = {\"output\": [{\"content\": [{\"type\": \"output_text\", \"text\": \"a\"}, {\"type\": \"output_text\", \"text\": \"b\"}]}]}
print(\"legacy:\", m._extract_text(p2) == \"a\\nb\")

# error payload
try:
    m._extract_text({\"error\": {\"message\": \"bad model\"}})
except m.OpenAIClientError as e:
    print(\"api error ok:\", e)

# malformed
try:
    m._extract_text({\"foo\": \"bar\"})
except m.OpenAIClientError as e:
    print(\"missing ok:\", e)

# empty prompt
c = m.OpenAIClient(api_key=\"sk-test\")
try:
    c.respond(\"\")
except m.OpenAIClientError as e:
    print(\"empty prompt ok:\", e)
PYEOF"

